import zipfile
import re
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}

def col_to_idx(ref):
    letters = re.match(r'[A-Z]+', ref).group()
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord('A') + 1)
    return idx - 1

def row_num(ref):
    return int(re.search(r'\d+', ref).group()) - 1

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    wb_xml = z.read('xl/workbook.xml').decode('utf-8')
    sheet_names = re.findall(r'<sheet[^>]*name="([^"]+)"[^>]*r:id="(rId\d+)"', wb_xml)
    rels_xml = z.read('xl/_rels/workbook.xml.rels').decode('utf-8')
    rel_map = dict(re.findall(r'Id="(rId\d+)"[^>]*Target="([^"]+)"', rels_xml))
    shared = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            shared.append(''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')))

    for name, rid in sheet_names:
        target = rel_map.get(rid, '')
        if not target.startswith('xl/'):
            target = 'xl/' + target.lstrip('/')
        path = target if target.endswith('.xml') else target + '.xml'
        print(f"=== Sheet: {name} ({path}) ===")
        root = ET.fromstring(z.read(path))
        for row in root.findall('.//m:row', NS):
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                if v is None or v.text is None:
                    continue
                val = v.text
                if t == 's':
                    val = shared[int(val)]
                elif t == 'b':
                    val = val == '1'
                elif t == 'str' or t == 'inlineStr':
                    pass
                else:
                    try:
                        val = float(val)
                        if val.is_integer():
                            val = int(val)
                    except ValueError:
                        pass
                print(f"{ref}: {val!r}")
        print()

