import zipfile
import re
import xml.etree.ElementTree as ET

M = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'

def parse_value(c):
    t = c.get('t')
    v = c.find(f'{{{M}}}v')
    if v is None or v.text is None:
        return None
    if t == 's':
        return v.text
    try:
        f = float(v.text)
        return int(f) if f.is_integer() else f
    except ValueError:
        return v.text

with zipfile.ZipFile('budget.xlsx') as z:
    root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    grid = {}
    for row in root.findall(f'.//{{{M}}}row'):
        for c in row.findall(f'{{{M}}}c'):
            ref = c.get('r')
            col = re.match(r'[A-Z]+', ref).group()
            row_i = int(re.search(r'\d+', ref).group())
            grid[(row_i, col)] = parse_value(c)

# Expenses rows: category (col A), item (col B), amount (col C)
expense_rows = []
for key, val in grid.items():
    row_i, col = key
    if col == 'C' and isinstance(val, (int, float)) and row_i >= 10:
        category = grid.get((row_i, 'A'))
        item = grid.get((row_i, 'B'))
        expense_rows.append((row_i, category, item, val))

print("Expense line items:")
for row_i, cat, item, val in expense_rows:
    print(f"  {cat} | {item} | {val}")

total = sum(v for _, _, _, v in expense_rows)
print(f"\nTotal expenses across all categories: {total}")

by_cat = {}
for _, cat, _, v in expense_rows:
    by_cat[cat] = by_cat.get(cat, 0) + v
print("\nBy category:")
for cat, v in by_cat.items():
    print(f"  {cat}: {v}")

